```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Function to generate the Fibonacci sequence
vector<int> fibonacci(int n) {
    if (n == 0 || n == 1) {
        return vector<int>{n};
    } else {
        return vector<int>{fibonacci(n - 1)[0], fibonacci(n - 2)[0] + fibonacci(n - 1)[1]};
    }
}

